from pathlib import Path


def replace_once(path: str, old: str, new: str):
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f'{path}: target not found: {old[:140]}')
    p.write_text(text.replace(old, new, 1))


